// The sweep's retried turns can end in handoff (R13.4). Each one is a customer waiting
// for a person who never comes unless this e-mail goes out. Empty list = no items = no e-mail.
const body = $input.first().json;
const list = Array.isArray(body.handoffs) ? body.handoffs : [];
return list.filter((h) => h && h.notify).map((h) => ({ json: h }));

