parameters.jsCode:
// WA-3: one item per touch the sweep decided to send. `via` (text or template) was decided
// by the Edge Function from the 24-hour window; nothing about it is decided here.
const body = $input.first().json;
const list = Array.isArray(body.send) ? body.send : [];
return list.filter((s) => s && s.to).map((s) => ({ json: s }));

// Security review 2026-09-25: a touch outside the 24-hour window with no approved template
// is cancelled by the Edge Function. Cancelled in silence, the operator never learns a
// template is missing; one e-mail per sweep that blocked something.
const body = $input.first().json;
const list = (Array.isArray(body.skipped) ? body.skipped : []).filter((s) => /janela de 24h/.test(String(s && s.reason)));
return list.length ? [{ json: { count: list.length, lines: list.map((s) => '- ' + s.followupId + ': ' + s.reason).join('\n') } }] : [];

